/**
 * n8n Code Node — Preparação do llmContext para o resumo de análise foliar — formato novo do backend
 *
 * Entrada (item único):
 *   { json: { field, value: { leafTissueAnalysis, foliarApplicationAdvices }, webHook, executionId } }
 *
 * Saída (item único):
 *   { llmContext: { sector, culture, leafTissueAnalysis, leafTissueAnalysisHistory,
 *                   foliarApplicationAdvices, associationStatus, dataWarnings }, _flowControl }
 *
 * O que mudou no formato do backend (e quebrou a versão anterior):
 *  - A análise agora é um objeto plano: não existe mais "samples" nem "period".
 *    sampleAt, season, biennial, note e values ficam direto na análise.
 *  - O setor vem em "sectors" (array), não mais em "sector".
 *  - values são números puros; as unidades vêm em originalValues.
 *
 * Regras decididas AQUI (a IA não reavalia):
 *  1. Setor e cultura saem só da análise foliar de referência (a mais recente).
 *     Área e propriedade não entram.
 *  2. Se vierem várias análises, ficam a 1ª e a última de cada ano; a mais recente
 *     é a referência e as demais vão para leafTissueAnalysisHistory.
 *  3. Ancoragem das recomendações de aplicação foliar à análise de referência:
 *       a) mesmo setor (por _id; se não houver _id, por nome)
 *       b) applicationDate não pode ser ANTERIOR à coleta
 *       c) applicationDate não pode passar de 60 dias APÓS a coleta
 *       d) ficam todas as que passarem, da mais próxima da coleta para a mais distante
 *  4. dataWarnings lista o que veio vazio/inconsistente e o que foi descartado.
 *
 * Ainda aceita o formato antigo (análise com "samples"): cada amostra vira uma análise.
 */
try {
  const inputItem = $input.first();
  if (!inputItem || !inputItem.json) {
    return [{ json: { error: "No input item received." } }];
  }

  const ABSENT = "ausente";
  const DAY_MS = 24 * 60 * 60 * 1000;
  const MAX_DAYS_AFTER = 60; // ~2 meses

  const _flowControl = {
    webHook: inputItem.json.webHook || ABSENT,
    executionId: inputItem.json.executionId || ABSENT,
  };

  // ===== 0. Leitura tolerante do payload =====
  let v = inputItem.json.value;
  if (typeof v === "string") {
    try {
      v = JSON.parse(v);
    } catch (e) {
      v = null;
    }
  }
  if (!isObj(v)) {
    return [{ json: { error: "Missing or invalid 'value' in payload." } }];
  }

  const candidate = v.leafTissueAnalysis ?? v.leafTissueAnalyses ?? (isObj(v.values) || Array.isArray(v.samples) ? v : undefined);

  // Formato antigo: { sector, samples: [...] } -> cada amostra herda setor/cultura do pai
  const rawList = toArray(candidate)
    .filter(isObj)
    .flatMap((a) =>
      Array.isArray(a.samples)
        ? a.samples.filter(isObj).map((s) => ({
            ...s,
            sectors: s.sectors || a.sectors || (a.sector ? [a.sector] : undefined),
            area: s.area || a.area,
            culture: s.culture || a.culture,
          }))
        : [a]
    )
    .filter((a) => Object.keys(a).length > 0);

  if (rawList.length === 0) {
    return [
      {
        json: {
          error:
            "Missing or invalid 'leafTissueAnalysis' in payload. Chaves recebidas em value: [" +
            Object.keys(v).join(", ") +
            "]",
        },
      },
    ];
  }

  const warnings = [];

  // ===== 1. Seleção: 1ª e última de cada ano; referência = a mais recente =====
  const { selected, undatedCount } = selectFirstLastPerYear(rawList);
  if (selected.length > 0 && undatedCount > 0) {
    warnings.push(`${undatedCount} análise(s) foliar(es) sem data de coleta válida foram ignoradas.`);
  }
  const finalSelection = selected.length > 0 ? selected : [{ raw: rawList[0], year: null }];
  const referenceRaw = finalSelection[finalSelection.length - 1].raw;
  const historyEntries = finalSelection.slice(0, -1);

  // ===== 2. Setor e cultura: fonte única = análise de referência =====
  const sectorRaw =
    (Array.isArray(referenceRaw.sectors) && referenceRaw.sectors.find(isObj)) ||
    (isObj(referenceRaw.sector) ? referenceRaw.sector : null) ||
    (isObj(v.sector) ? v.sector : null) ||
    {};

  const sector = {
    name: sectorRaw.name || ABSENT,
    size: sectorRaw.size ?? ABSENT,
    plantingDate: sectorRaw.plantingDate ? String(sectorRaw.plantingDate).split("T")[0] : ABSENT,
    amountOfPlants: sectorRaw.amountOfPlants ?? ABSENT,
    plantSpacing: sectorRaw.plantSpacing ?? ABSENT,
    lineSpacing: sectorRaw.lineSpacing ?? ABSENT,
  };
  if (!sectorRaw._id && !sectorRaw.name) {
    warnings.push("A análise foliar veio sem setor; não é possível associar recomendações de aplicação a ela.");
  }

  // A IA usa a cultura para escolher a tabela de referência nutricional.
  const culture = referenceRaw.area?.culture || referenceRaw.culture || v.area?.culture || ABSENT;
  if (referenceRaw.area?.culture && referenceRaw.culture && referenceRaw.area.culture !== referenceRaw.culture) {
    warnings.push(
      `A cultura vem com dois códigos diferentes no cadastro: "${referenceRaw.area.culture}" (área) e "${referenceRaw.culture}" (análise). Foi usado o da área.`
    );
  }

  // ===== 3. Análise de referência + histórico =====
  const leafTissueAnalysis = buildLeafAnalysis(referenceRaw, ABSENT);
  const historyResult = historyEntries.map((e) => ({ year: e.year ?? ABSENT, ...buildLeafAnalysis(e.raw, ABSENT) }));
  const leafTissueAnalysisHistory = historyResult.length > 0 ? historyResult : ABSENT;

  if (leafTissueAnalysis.values === ABSENT) {
    warnings.push(`A análise foliar "${leafTissueAnalysis.name}" veio sem nenhum teor de nutriente.`);
  }

  // ===== 4. Recomendações: dedup por _id =====
  const seenIds = new Set();
  const advices = toArray(v.foliarApplicationAdvices).filter((adv) => {
    if (!isObj(adv)) return false;
    if (!adv._id) return true;
    if (seenIds.has(adv._id)) return false;
    seenIds.add(adv._id);
    return true;
  });

  // ===== 5. Ancoragem: mesmo setor + janela de 0 a 60 dias após a coleta =====
  const anchorT = Date.parse(sampleDateOf(referenceRaw));
  const discarded = { otherSector: 0, noDate: 0, before: 0, tooLate: 0 };
  const matched = [];

  const sameSector = (adv) =>
    toArray(adv.sectors).some((s) =>
      isObj(s) && (sectorRaw._id && s._id ? s._id === sectorRaw._id : !!sectorRaw.name && s.name === sectorRaw.name)
    );

  for (const adv of advices) {
    if (!sameSector(adv)) {
      discarded.otherSector++;
      continue;
    }
    const appT = Date.parse(adv.applicationDate);
    if (Number.isNaN(anchorT) || Number.isNaN(appT)) {
      discarded.noDate++;
      continue;
    }
    const diffDays = Math.round((appT - anchorT) / DAY_MS);
    if (diffDays < 0) discarded.before++;
    else if (diffDays > MAX_DAYS_AFTER) discarded.tooLate++;
    else matched.push({ adv, diffDays });
  }
  matched.sort((a, b) => a.diffDays - b.diffDays);

  if (Number.isNaN(anchorT) && advices.length > 0) {
    warnings.push("A análise foliar não tem data de coleta válida; nenhuma recomendação de aplicação pôde ser associada.");
  }
  if (discarded.otherSector) warnings.push(`${discarded.otherSector} recomendação(ões) de aplicação foliar de outro setor foram descartadas.`);
  if (discarded.noDate && !Number.isNaN(anchorT)) warnings.push(`${discarded.noDate} recomendação(ões) de aplicação foliar sem data de aplicação foram descartadas.`);
  if (discarded.before) warnings.push(`${discarded.before} recomendação(ões) de aplicação foliar anteriores à coleta foram descartadas.`);
  if (discarded.tooLate) warnings.push(`${discarded.tooLate} recomendação(ões) de aplicação foliar com mais de ${MAX_DAYS_AFTER} dias após a coleta foram descartadas.`);

  if (advices.length === 0) {
    warnings.push("foliarApplicationAdvices veio vazio: nenhuma recomendação de aplicação foliar foi recebida.");
  }
  if (referenceRaw.linkedToAdvice === true && matched.length === 0) {
    warnings.push(
      `A análise "${leafTissueAnalysis.name}" está marcada como vinculada a uma recomendação (linkedToAdvice), mas nenhuma recomendação foi associada a ela.`
    );
  }

  // ===== 6. Limpeza das recomendações associadas (sem repetir setor/área/propriedade) =====
  const foliarApplicationAdvices = matched.map(({ adv, diffDays }) => {
    const products = toArray(adv.products).filter(isObj);
    if (products.length === 0) {
      warnings.push(`Recomendação "${adv.name || adv._id}": veio sem produtos.`);
    }
    return {
      name: adv.name || ABSENT,
      category: adv.category || ABSENT,
      applicationDate: String(adv.applicationDate).split("T")[0],
      daysAfterSampling: diffDays,
      tankVolume: adv.tankVolume ?? ABSENT,
      syrupVolume: adv.syrupVolume ?? ABSENT,
      tanksToPrepare: adv.tanksToPrepare ?? ABSENT,
      products:
        products.length > 0
          ? products.map((p) => ({
              name: p.productCommercialName || p.product?.name || ABSENT,
              tradeMark: p.productTradeMark || ABSENT,
              class: p.productClass || ABSENT,
              dose: p.dose ?? ABSENT,
              doseUnit: p.doseMeasurementUnit || ABSENT,
              quantityPerTank: p.quantityPerTank ?? ABSENT,
              totalNecessary: p.totalNecessary ?? ABSENT,
            }))
          : ABSENT,
    };
  });

  return [
    {
      json: {
        llmContext: {
          sector,
          culture,
          leafTissueAnalysis,
          leafTissueAnalysisHistory,
          foliarApplicationAdvices,
          // A associação já foi decidida aqui; a IA só usa o resultado.
          associationStatus: foliarApplicationAdvices.length > 0 ? "matched" : "none",
          dataWarnings: warnings.length > 0 ? [...new Set(warnings)] : ABSENT,
        },
        _flowControl,
      },
    },
  ];
} catch (err) {
  const message = err instanceof Error ? err.message : String(err);
  return [{ json: { error: message } }];
}

// ===== FUNÇÕES AUXILIARES =====

function toArray(v) {
  return Array.isArray(v) ? v : v ? [v] : [];
}

function isObj(v) {
  return v !== null && typeof v === "object" && !Array.isArray(v);
}

// A análise foliar usa "sampleAt"; aceita "sampledAt" por segurança.
function sampleDateOf(raw) {
  return raw.sampleAt || raw.sampledAt || null;
}

// Primeira e última análise de cada ano (pela data de coleta), em ordem cronológica.
function selectFirstLastPerYear(list) {
  const dated = list
    .map((raw) => ({ raw, t: Date.parse(sampleDateOf(raw)) }))
    .filter((x) => !Number.isNaN(x.t))
    .sort((a, b) => a.t - b.t);

  const byYear = new Map();
  for (const item of dated) {
    const year = new Date(item.t).getUTCFullYear();
    if (!byYear.has(year)) byYear.set(year, { first: item, last: item });
    else byYear.get(year).last = item;
  }

  const selected = [];
  for (const [year, { first, last }] of byYear) {
    selected.push({ raw: first.raw, year });
    if (last !== first) selected.push({ raw: last.raw, year });
  }
  return { selected, undatedCount: list.length - dated.length };
}

// Junta values (números) com originalValues (unidades). Aceita também values já
// no formato { value, unit, normalizedValue, normalizedUnit }.
function buildLeafAnalysis(raw, ABSENT) {
  const flat = isObj(raw.values) ? raw.values : {};
  const detailed = isObj(raw.originalValues) ? raw.originalValues : {};

  const values = {};
  const conversions = {};
  const params = new Set([...Object.keys(flat), ...Object.keys(detailed)]);

  for (const param of params) {
    const info = isObj(flat[param]) ? flat[param] : isObj(detailed[param]) ? detailed[param] : {};
    const plain = isObj(flat[param]) ? undefined : flat[param];

    const val = plain ?? info.normalizedValue ?? info.value;
    if (val === undefined || val === null || val === "") continue;

    const unit = info.normalizedUnit ?? info.unit ?? "";
    values[param] = unit ? `${val} ${unit}` : `${val}`;

    // Só registra conversão quando o laudo original difere do valor normalizado
    const hasOriginal = info.value !== undefined && info.value !== null;
    const valueChanged = hasOriginal && info.normalizedValue != null && info.value !== info.normalizedValue;
    const unitChanged = hasOriginal && info.unit && info.normalizedUnit && info.unit !== info.normalizedUnit;
    if (valueChanged || unitChanged) {
      conversions[param] = `original: ${info.value} ${info.unit ?? ""}`.trim();
    }
  }

  const date = sampleDateOf(raw);
  return {
    id: raw._id || ABSENT,
    name: raw.name || ABSENT,
    sampleAt: date ? String(date).split("T")[0] : ABSENT,
    season: raw.season || ABSENT,
    biennial: raw.biennial || ABSENT,
    note: raw.note ? String(raw.note).replace(/\s+/g, " ").trim() : ABSENT,
    values: Object.keys(values).length > 0 ? values : ABSENT,
    conversions: Object.keys(conversions).length > 0 ? conversions : ABSENT,
  };
}

