/**
 * n8n Code Node — Preparação de Payload Enxuto para IA (LLM) — formato novo do backend
 *
 * Entrada (item único):
 *   { json: { field, value: { soilAnalyses, fertilizerPlans, plantAdvices }, webHook, executionId } }
 *
 * Saída (item único):
 *   { llmContext: { property, sector, culture, soilAnalysis, soilAnalysisHistory,
 *                   fertilizerPlans, plantAdvices, dataWarnings }, _flowControl }
 *
 * O que mudou em relação à versão anterior:
 *  - soilAnalyses.values agora são números puros; as unidades vêm em originalValues
 *    ({ value, unit, normalizedValue, normalizedUnit }). O nó junta os dois.
 *  - "conversions" só aparece quando houve conversão de verdade.
 *  - Toda análise leva "id", para cruzar com fertilizerPlans.soilAnalysisId e
 *    plantAdvices.soilAnalysisId.
 *  - fertilizerPlans: saldo agregado por mês (era por semana), referência à recomendação
 *    de corretivo (plantingAdvice), florada, modo de aplicação e pacote de produtos.
 *  - dataWarnings: lista o que veio vazio/inconsistente da API, para o agente não
 *    interpretar "dado faltando" como "nada foi feito".
 *  - Campo sem valor = "ausente" em todo lugar (não há mais mistura com null).
 */
try {
  const inputItem = $input.first();
  if (!inputItem || !inputItem.json) {
    return [{ json: { error: "No input item received." } }];
  }

  const ABSENT = "ausente";
  const INCLUDE_PRODUCT_PACK = true; // false = não envia o pacote de produtos do plano

  const webHook = inputItem.json.webHook || ABSENT;
  const executionId = inputItem.json.executionId || ABSENT;
  const _flowControl = { webHook, executionId };

  const rawValue = inputItem.json.value;
  if (!rawValue || typeof rawValue !== "object") {
    return [{ json: { error: "Missing or invalid 'value' in payload." } }];
  }

  const warnings = [];

  // ===================================================================
  // 1. soilAnalyses — 1ª e última de cada ano + análise de referência
  // ===================================================================
  const rawList = toArray(rawValue.soilAnalyses).filter(
    (a) => a && typeof a === "object" && Object.keys(a).length > 0
  );
  if (rawList.length === 0) {
    return [{ json: { error: "Missing or invalid 'soilAnalyses' in payload." } }];
  }

  const { selected, undatedCount } = selectFirstLastPerYear(rawList);
  if (selected.length > 0 && undatedCount > 0) {
    warnings.push(`${undatedCount} análise(s) de solo sem data válida (sampledAt) foram ignoradas.`);
  }

  // Fallback: nenhuma análise com data válida -> usa a primeira recebida
  const finalSelection = selected.length > 0 ? selected : [{ raw: rawList[0], year: null }];
  const referenceRaw = finalSelection[finalSelection.length - 1].raw; // a mais recente
  const historyEntries = finalSelection.slice(0, -1);

  const sector = buildSector(referenceRaw, ABSENT);
  const culture = referenceRaw.area?.culture || ABSENT;
  const property = {
    name: referenceRaw.prop?.name || ABSENT,
    state: referenceRaw.prop?.state || ABSENT,
    area: referenceRaw.area?.name || ABSENT,
  };

  const soilAnalysis = buildSoilAnalysis(referenceRaw, ABSENT);
  const historyResult = historyEntries.map((e) => ({ year: e.year ?? ABSENT, ...buildSoilAnalysis(e.raw, ABSENT) }));
  const soilAnalysisHistory = historyResult.length > 0 ? historyResult : ABSENT;

  const knownSoilIds = new Set(rawList.map((a) => a._id).filter(Boolean));

  // ===================================================================
  // 2. plantAdvices — recomendações de corretivo (calagem/gessagem/adubação)
  // ===================================================================
  const seenIds = new Set();
  const plantAdvices = toArray(rawValue.plantAdvices)
    .filter((adv) => {
      if (!adv || typeof adv !== "object") return false;
      if (!adv._id) return true;
      if (seenIds.has(adv._id)) return false;
      seenIds.add(adv._id);
      return true;
    })
    .map((adv) => {
      // Parâmetros com que a dose de calagem foi de fato calculada (metadatas)
      const calcMeta = toArray(adv.metadatas).find((m) => isObj(m) && m.resource === "calcularCalagem")?.meta;
      if (adv.calagem && isObj(calcMeta) && calcMeta.metodo && adv.calagem.metodo && calcMeta.metodo !== adv.calagem.metodo) {
        warnings.push(
          `Recomendação "${adv.name || adv._id}": o método de calagem diverge entre o cadastro (${adv.calagem.metodo}) e o cálculo registrado (${calcMeta.metodo}).`
        );
      }
      const hasAdubacao = isObj(adv.adubacao) && Array.isArray(adv.adubacao.products) && adv.adubacao.products.length > 0;
      return {
      id: adv._id || ABSENT,
      name: adv.name || ABSENT,
      soilAnalysisId: refId(adv.soilAnalysis) || ABSENT,
      note: adv.note || ABSENT,
      calagem: adv.calagem
        ? {
            metodo: adv.calagem.metodo || ABSENT,
            metodoValue: adv.calagem.metodoValue ?? ABSENT,
            product: productLabel(adv.calagem.product) || ABSENT,
            dose: adv.calagem.dose ?? ABSENT,
            doseMax: calcMeta?.doseMax ?? ABSENT,
            forma: adv.calagem.forma || ABSENT,
            formaValue: adv.calagem.formaValue ?? ABSENT,
            formaAplicacao: adv.formasAplicacao?.[adv.calagem.forma] ?? calcMeta?.formaAplicacao ?? ABSENT,
            CaO: adv.calagem.CaO ?? ABSENT,
            MgO: adv.calagem.MgO ?? ABSENT,
          }
        : ABSENT,
      gessagem: adv.gessagem
        ? {
            product: productLabel(adv.gessagem.product) || ABSENT,
            dose: adv.gessagem.dose ?? ABSENT,
            forma: adv.gessagem.forma || ABSENT,
            formaValue: adv.gessagem.formaValue ?? ABSENT,
            interpretacao: adv.gessagem.interpretacao || ABSENT,
            CaO: adv.gessagem.CaO ?? ABSENT,
            S: adv.gessagem.S ?? ABSENT,
          }
        : ABSENT,
      // adubacao com lista de produtos vazia = não há adubação na recomendação
      adubacao: hasAdubacao
        ? {
            forma: adv.adubacao.forma || ABSENT,
            products: adv.adubacao.products.map((p) => ({
              name: productLabel(p.product) || ABSENT,
              dose: p.dose ?? ABSENT,
              formaValue: p.formaValue ?? ABSENT,
              N: p.N ?? ABSENT,
              P2O5: p.P2O5 ?? ABSENT,
              K2O: p.K2O ?? ABSENT,
            })),
          }
        : ABSENT,
      projectedResult: isObj(adv.resultado) && Object.keys(adv.resultado).length > 0 ? adv.resultado : ABSENT,
      };
    });

  const adviceIds = new Set(plantAdvices.map((a) => a.id));

  if (plantAdvices.length === 0) {
    warnings.push("plantAdvices veio vazio: nenhuma recomendação de corretivo (calagem/gessagem/adubação) foi recebida.");
  }
  for (const a of rawList) {
    if (a.linkedToAdvice === true && !plantAdvices.some((adv) => adv.soilAnalysisId === a._id)) {
      warnings.push(
        `A análise "${a.name || a._id}" está marcada como vinculada a uma recomendação (linkedToAdvice), mas essa recomendação não veio em plantAdvices.`
      );
    }
  }

  // ===================================================================
  // 3. fertilizerPlans — visão agregada do plano de manutenção
  // ===================================================================
  const NUTRIENT_ORDER = ["N", "P2O5", "K2O", "Ca", "Mg", "S", "B", "Cu", "Fe", "Mn", "Mo", "Zn"];
  const KNOWN_NUTRIENTS = new Set([...NUTRIENT_ORDER, "CaO", "MgO"]);

  const fertilizerPlans = toArray(rawValue.fertilizerPlans)
    .filter((rec) => rec && typeof rec === "object")
    .map((rec) => {
      const label = rec.name || rec._id || "sem nome";

      // --- Demanda anual: só chaves que são nutrientes de verdade ---
      const annualDemand = {};
      const invalidKeys = [];
      for (const [key, value] of Object.entries(isObj(rec.demandAnnual) ? rec.demandAnnual : {})) {
        const v = isObj(value) ? value.normalizedValue ?? value.value : value;
        if (!KNOWN_NUTRIENTS.has(key)) invalidKeys.push(`${key}=${JSON.stringify(v)}`);
        else if (v !== undefined && v !== null) annualDemand[key] = v;
      }
      if (invalidKeys.length > 0) {
        warnings.push(
          `Plano "${label}": demandAnnual veio com chave(s) inválida(s) (${invalidKeys.join(", ")}); não dá para saber a qual nutriente o valor pertence.`
        );
      }
      if (Object.keys(annualDemand).length === 0 && invalidKeys.length === 0) {
        warnings.push(`Plano "${label}": sem demanda anual por nutriente.`);
      }

      // --- Saldo demanda x aplicado, agregado por mês ---
      const balance = buildMonthlyBalance(rec.nutrientBalance, Object.keys(annualDemand), NUTRIENT_ORDER);
      if (balance.inferredNames) {
        warnings.push(
          `Plano "${label}": os nutrientes do saldo foram identificados pela posição no array (${balance.names.join(", ")}), não por nome.`
        );
      }
      if (Array.isArray(rec.nutrientBalance) && rec.nutrientBalance.length > 0 && balance.months.length === 0) {
        warnings.push(
          `Plano "${label}": nutrientBalance tem ${rec.nutrientBalance.length} períodos, todos com demanda e aplicação zeradas.`
        );
      }
      if (Array.isArray(rec.fertilizations) && rec.fertilizations.length === 0) {
        warnings.push(`Plano "${label}": nenhuma fertilização registrada como aplicada.`);
      }

      // --- Vínculos ---
      const soilAnalysisId = refId(rec.soilAnalysis);
      if (soilAnalysisId && !knownSoilIds.has(soilAnalysisId)) {
        warnings.push(`Plano "${label}": a análise de solo em que ele se baseia (${soilAnalysisId}) não veio no payload.`);
      }

      let correctiveAdvice = ABSENT;
      if (isObj(rec.plantingAdvice)) {
        const advId = rec.plantingAdvice._id || ABSENT;
        const advSoilId = refId(rec.plantingAdvice.soilAnalysis);
        correctiveAdvice = {
          id: advId,
          name: rec.plantingAdvice.name || ABSENT,
          soilAnalysisId: advSoilId || ABSENT,
        };
        if (!adviceIds.has(advId)) {
          warnings.push(
            `Plano "${label}": referencia a recomendação de corretivo "${correctiveAdvice.name}", mas o conteúdo dela (doses de calagem/gessagem) não veio em plantAdvices.`
          );
        }
        if (advSoilId && !knownSoilIds.has(advSoilId)) {
          warnings.push(
            `A recomendação "${correctiveAdvice.name}" foi feita sobre outra análise de solo (${advSoilId}), que não veio no payload.`
          );
        }
      }

      // --- Modo de aplicação (vem em generatedRecommendations) ---
      const gen = toArray(rec.generatedRecommendations).find(isObj);
      const application = gen
        ? { method: gen.method || ABSENT, irrigationType: gen.irrigationType || ABSENT }
        : ABSENT;

      const plan = {
        name: rec.name || ABSENT,
        soilAnalysisId: soilAnalysisId || ABSENT,
        cropStage: rec.cropStage || ABSENT,
        productivity: rec.productivity ?? ABSENT,
        startingPeriod: rec.startingPeriod || ABSENT,
        floweringDate: rec.floweringDate || ABSENT,
        parcelling: rec.parcelling?.name || ABSENT,
        application,
        correctiveAdvice,
        nutrients: {
          annualDemand: Object.keys(annualDemand).length > 0 ? annualDemand : ABSENT,
          monthlyBalance: balance.months.length > 0 ? balance.months : ABSENT,
        },
      };

      if (INCLUDE_PRODUCT_PACK) {
        plan.productPack = buildProductPack(rec.generatedCombo, ABSENT);
      }
      return plan;
    });

  if (fertilizerPlans.length === 0) {
    warnings.push("fertilizerPlans veio vazio: nenhum plano de manutenção foi recebido.");
  }

  return [
    {
      json: {
        llmContext: {
          property,
          sector,
          culture,
          soilAnalysis,
          soilAnalysisHistory,
          fertilizerPlans,
          plantAdvices,
          dataWarnings: warnings.length > 0 ? [...new Set(warnings)] : ABSENT,
        },
        _flowControl,
      },
    },
  ];
} catch (err) {
  const message = err instanceof Error ? err.message : String(err);
  return [{ json: { error: message } }];
}

// ===== FUNÇÕES AUXILIARES =====

function toArray(v) {
  return Array.isArray(v) ? v : v ? [v] : [];
}

function isObj(v) {
  return v !== null && typeof v === "object" && !Array.isArray(v);
}

// Referência pode vir como string (id) ou objeto populado ({ _id, ... })
function refId(ref) {
  if (typeof ref === "string") return ref;
  return isObj(ref) ? ref._id || null : null;
}

// Produto pode vir como objeto populado ({ name }) ou só o id
function productLabel(product) {
  if (isObj(product)) return product.name || product._id || null;
  return typeof product === "string" ? product : null;
}

function round(n, decimals = 4) {
  const f = 10 ** decimals;
  return Math.round(n * f) / f;
}

// Primeira e última análise de cada ano (por sampledAt), em ordem cronológica.
function selectFirstLastPerYear(list) {
  const dated = list
    .map((raw) => ({ raw, t: Date.parse(raw.sampledAt) }))
    .filter((x) => !Number.isNaN(x.t))
    .sort((a, b) => a.t - b.t);

  const byYear = new Map();
  for (const item of dated) {
    const year = new Date(item.t).getUTCFullYear();
    if (!byYear.has(year)) byYear.set(year, { first: item, last: item });
    else byYear.get(year).last = item;
  }

  const selected = [];
  for (const [year, { first, last }] of byYear) {
    selected.push({ raw: first.raw, year });
    if (last !== first) selected.push({ raw: last.raw, year });
  }
  return { selected, undatedCount: list.length - dated.length };
}

function buildSector(rawSoilAnalysis, ABSENT) {
  const s = (Array.isArray(rawSoilAnalysis.sectors) && rawSoilAnalysis.sectors[0]) || {};
  return {
    name: s.name || ABSENT,
    size: s.size ?? ABSENT,
    plantingDate: s.plantingDate ? String(s.plantingDate).split("T")[0] : ABSENT,
    amountOfPlants: s.amountOfPlants ?? ABSENT,
    plantSpacing: s.plantSpacing ?? ABSENT,
    lineSpacing: s.lineSpacing ?? ABSENT,
  };
}

// Junta values (números) com originalValues (unidades). Aceita também o formato
// antigo, em que values[param] já era { value, unit, normalizedValue, normalizedUnit }.
function buildSoilAnalysis(raw, ABSENT) {
  const NO_UNIT = new Set(["ph", "ratio", ""]); // "5.2 pH" e "2.12 ratio" são ruído
  const flat = isObj(raw.values) ? raw.values : {};
  const detailed = isObj(raw.originalValues) ? raw.originalValues : {};

  const values = {};
  const conversions = {};
  const params = new Set([...Object.keys(flat), ...Object.keys(detailed)]);

  for (const param of params) {
    const info = isObj(flat[param]) ? flat[param] : isObj(detailed[param]) ? detailed[param] : {};
    const plain = isObj(flat[param]) ? undefined : flat[param];

    const val = plain ?? info.normalizedValue ?? info.value;
    if (val === undefined || val === null || val === "") continue;

    const unit = info.normalizedUnit ?? info.unit ?? "";
    values[param] = NO_UNIT.has(String(unit).toLowerCase()) ? `${val}` : `${val} ${unit}`;

    // Só registra conversão quando o laudo original difere do valor normalizado
    const hasOriginal = info.value !== undefined && info.value !== null;
    const valueChanged = hasOriginal && info.normalizedValue != null && info.value !== info.normalizedValue;
    const unitChanged = hasOriginal && info.unit && info.normalizedUnit && info.unit !== info.normalizedUnit;
    if (valueChanged || unitChanged) {
      conversions[param] = `original: ${info.value} ${info.unit ?? ""}`.trim();
    }
  }

  return {
    id: raw._id || ABSENT,
    name: raw.name || ABSENT,
    sampledAt: raw.sampledAt ? String(raw.sampledAt).split("T")[0] : ABSENT,
    note: raw.note ? String(raw.note).replace(/\s+/g, " ").trim() : ABSENT,
    values: Object.keys(values).length > 0 ? values : ABSENT,
    conversions: Object.keys(conversions).length > 0 ? conversions : ABSENT,
  };
}

// Agrega nutrientBalance (semanal) por mês: { period: "2026/10", nutrients: { N: { demand, applied, balance } } }
// Meses sem demanda nem aplicação ficam de fora.
// Nomes dos nutrientes: chaves de demandAnnual se baterem com o tamanho dos arrays;
// senão, ordem padrão (12 posições, ou 11 sem Mo) — nesse caso inferredNames = true.
function buildMonthlyBalance(nutrientBalance, annualKeys, NUTRIENT_ORDER) {
  const items = (Array.isArray(nutrientBalance) ? nutrientBalance : []).filter(isObj);
  const width = items.reduce(
    (m, it) => Math.max(m, Array.isArray(it.demand) ? it.demand.length : 0, Array.isArray(it.applied) ? it.applied.length : 0),
    0
  );

  let names;
  let positional = false;
  if (annualKeys.length > 0 && annualKeys.length === width) {
    names = annualKeys;
  } else {
    positional = true;
    if (width === NUTRIENT_ORDER.length) names = NUTRIENT_ORDER;
    else if (width === NUTRIENT_ORDER.length - 1) names = NUTRIENT_ORDER.filter((n) => n !== "Mo");
    else names = Array.from({ length: width }, (_, i) => NUTRIENT_ORDER[i] || `nutriente_${i + 1}`);
  }

  const byMonth = new Map();
  for (const item of items) {
    const month = item.period ? String(item.period).slice(0, 7) : "sem período";
    if (!byMonth.has(month)) byMonth.set(month, {});
    const acc = byMonth.get(month);
    const demand = Array.isArray(item.demand) ? item.demand : [];
    const applied = Array.isArray(item.applied) ? item.applied : [];

    names.forEach((name, i) => {
      const d = Number(demand[i]) || 0;
      const a = Number(applied[i]) || 0;
      if (d === 0 && a === 0) return;
      if (!acc[name]) acc[name] = { demand: 0, applied: 0 };
      acc[name].demand += d;
      acc[name].applied += a;
    });
  }

  const months = [];
  for (const [period, acc] of byMonth) {
    const nutrients = {};
    for (const [name, { demand, applied }] of Object.entries(acc)) {
      nutrients[name] = { demand: round(demand), applied: round(applied), balance: round(demand - applied) };
    }
    if (Object.keys(nutrients).length > 0) months.push({ period, nutrients });
  }

  return { months, names, inferredNames: positional && months.length > 0 };
}

// Pacote de produtos do plano: só nome + garantias diferentes de zero.
function buildProductPack(generatedCombo, ABSENT) {
  if (!isObj(generatedCombo)) return ABSENT;
  const GUARANTEES = ["N", "P2O5", "K2O", "Ca", "CaO", "Mg", "MgO", "S", "B", "Cu", "Fe", "Mn", "Mo", "Zn", "PRNT"];

  const products = toArray(generatedCombo.products)
    .filter(isObj)
    .map((p) => {
      const guarantees = {};
      for (const g of GUARANTEES) {
        if (typeof p[g] === "number" && p[g] !== 0) guarantees[g] = p[g];
      }
      return {
        name: p.name || ABSENT,
        guaranteesPct: Object.keys(guarantees).length > 0 ? guarantees : ABSENT,
        applicationMethods:
          Array.isArray(p.applicationMethods) && p.applicationMethods.length > 0 ? p.applicationMethods : ABSENT,
      };
    });

  return {
    name: generatedCombo.selection?.name || ABSENT,
    products: products.length > 0 ? products : ABSENT,
  };
}

