/**
 * n8n Code Node — Reduz soilAnalysisHistory.samples
 * Mantém, por ano, apenas a PRIMEIRA e a ÚLTIMA data de coleta.
 * Saída ordenada cronologicamente, mesmo formato da entrada.
 */
try {
  const inputItem = $input.first();
  if (!inputItem || !inputItem.json) {
    return [{ json: { error: "No input item received." } }];
  }

  // Se true, quando há várias amostras na MESMA data (primeira = última),
  // mantém todas elas. Se false, mantém só uma por data.
  const KEEP_ALL_ON_SAME_DATE = false;

  const json = inputItem.json;
  const value = json.value;

  if (!value || typeof value !== "object" || !Array.isArray(value.samples)) {
    return [{ json }]; // nada a filtrar, segue o fluxo sem alterar
  }

  // 1) Datas válidas + ordenação cronológica (estável: empate mantém ordem original)
  const dated = value.samples
    .map((sample, idx) => ({ sample, idx, t: Date.parse(sample?.sampledAt) }))
    .filter((x) => !Number.isNaN(x.t))
    .sort((a, b) => a.t - b.t || a.idx - b.idx);

  if (dated.length === 0) {
    return [{ json }]; // nenhuma data válida, mantém como veio
  }

  // 2) Agrupa por ano e guarda o menor e o maior dia de cada ano
  const byYear = new Map();
  for (const item of dated) {
    const year = new Date(item.t).getUTCFullYear();
    if (!byYear.has(year)) byYear.set(year, []);
    byYear.get(year).push(item);
  }

  const selected = [];
  for (const [, items] of byYear) {
    const firstT = items[0].t;
    const lastT = items[items.length - 1].t;

    if (firstT === lastT) {
      // todas na mesma data
      if (KEEP_ALL_ON_SAME_DATE) selected.push(...items);
      else selected.push(items[0]);
    } else {
      selected.push(items[0]); // primeira do ano
      selected.push(items[items.length - 1]); // última do ano
    }
  }

  selected.sort((a, b) => a.t - b.t || a.idx - b.idx);
  const samples = selected.map((x) => x.sample);

  // 3) Recalcula metadados
  const dates = samples.map((s) => String(s.sampledAt).split("T")[0]);
  const distinctDates = new Set(dates).size;
  const sortedDates = [...dates].sort();

  const newValue = {
    ...value,
    totalSamplesOriginal: value.totalSamples ?? value.samples.length,
    totalSamples: samples.length,
    distinctDates,
    period: { start: sortedDates[0], end: sortedDates[sortedDates.length - 1] },
    samples,
  };

  return [{ json: { ...json, value: newValue } }];
} catch (err) {
  const message = err instanceof Error ? err.message : String(err);
  return [{ json: { error: message } }];
}
